//! 🧪️ Child identity is issued once; every callback, failed return and close spends the same real caller.
use semio_framework_job::*;
use std::cell::Cell;
#[global_allocator]
static ORIGINAL_SOURCE_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
thread_local!{static NOW:Cell<u64>=const{Cell::new(1000)};}
fn clock()->Option<u64>{Some(NOW.with(Cell::get))}
fn observe<T>(run:impl FnOnce()->T)->(T,(usize,usize)){let(value,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(run);(value,(heap.requested_bytes,heap.released_bytes))}
fn grant(row:&serde_json::Value)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:row[0].as_u64().unwrap()as usize,maximum_copy_bytes:row[1].as_u64().unwrap()as usize,maximum_capacity_bytes:row[2].as_u64().unwrap()as usize,maximum_release_bytes:row[3].as_u64().unwrap()as usize,maximum_depth:row[4].as_u64().unwrap()as usize}}
fn metadata()->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,..Default::default()}}
fn work<R>(caller:&mut OriginalJobFixtureCaller,grant:RetainedCloneGrant,fuel:u64,deadline:u64,run:impl FnOnce(&OriginalCallerSourceParent,&mut StepContext<'_>)->Result<R,OriginalTurnFailure>)->Result<R,OriginalTurnFailure>{let mut received=None;caller.turn(grant,|cx|cx.with_original_work_loan(fuel,deadline,|cx|{received=Some(run(cx.original_source_parent()?,cx)?);Ok(())}))?;Ok(received.unwrap())}
#[derive(semio_framework_value::RetireOwned)]
struct OwnedSemantic{bytes:[u8;7]}
#[test]
fn original_child_source_issues_business_identity_once_and_closes_every_paid_prefix_under_same_parent(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let initial=grant(&law["initialGrant"]);let stock=grant(&law["initialStock"]);let callback=grant(&law["callbackGrant"]);let close=grant(&law["closeGrant"]);let operation=OperationId(law["parent"]["operation"].as_u64().unwrap());let generation=Generation(law["parent"]["generation"].as_u64().unwrap());let child_operation=OperationId(law["child"]["operation"].as_u64().unwrap());let child_generation=Generation(law["child"]["generation"].as_u64().unwrap());
 for cut in law["cuts"].as_array().unwrap(){NOW.with(|now|now.set(1000));let cut=cut.as_u64().unwrap()as usize;let(mut caller,heap)=observe(||OriginalJobFixtureCaller::admit(operation,generation,stock,clock,law["initialDeadline"].as_u64().unwrap(),law["initialFuel"].as_u64().unwrap()));let mut born=heap.0;assert_eq!(born,caller.born_bytes());let(parent_identity,parent_ledger)=caller.turn(initial,|cx|Ok((cx.original_source_parent()?.source_identity()?,cx.payload_authority_identity()))).unwrap();let mut source=None;let mut released=0;
  if cut>0{
   let(answer,heap)=observe(||work(&mut caller,initial,4,100000,|parent,cx|OriginalCallerChildSource::begin(parent,cx,child_operation,child_generation)));source=answer.unwrap();assert!(source.is_some());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),metadata());
   for phase in 1..cut{let(answer,heap)=observe(||work(&mut caller,initial,4,100000,|parent,cx|source.as_mut().unwrap().admit_step(parent,cx)));assert!(!answer.unwrap());let actual=caller.receipt();assert_eq!([actual.copied_items,actual.copied_bytes,actual.retained_capacity_bytes,actual.released_bytes],law["admission"][phase]["spent"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap()as usize).collect::<Vec<_>>().as_slice());assert_eq!(heap,(actual.retained_capacity_bytes,actual.released_bytes));born+=heap.0;released+=heap.1;}
   if cut==4{
    let child=source.as_mut().unwrap();let(answer,heap)=observe(||work(&mut caller,initial,4,100000,|parent,cx|child.admit_step(parent,cx)));assert!(answer.unwrap());assert_eq!(heap,(0,0));assert_eq!(caller.receipt(),Default::default());let child_ledger=child.parent().unwrap().payload_authority_identity().unwrap();assert_ne!(child_ledger,parent_ledger);
    for incoming in law["incoming"].as_array().unwrap(){NOW.with(|now|now.set(incoming["clock"].as_u64().unwrap()));let fuel=incoming["fuel"].as_u64().unwrap();let deadline=incoming["deadline"].as_u64().unwrap();let(answer,heap)=observe(||work(&mut caller,callback,fuel,deadline,|parent,cx|{let recipient=cx.original_recipient_identity();child.with_context(parent,cx,callback,|actual|{assert_eq!((actual.operation(),actual.generation()),(child_operation,child_generation));assert_eq!(actual.deadline_us(),deadline);assert_eq!(actual.fuel_remaining(),fuel);assert_eq!(actual.original_recipient_identity(),recipient);assert_eq!(actual.payload_authority_identity(),child_ledger);assert!(actual.original_cancel_token().is_same_node(parent.cancellation()?));assert_eq!(actual.clock_source()(),incoming["clock"].as_u64());assert!(std::ptr::eq(actual.original_source_parent()?,child.parent()?));if fuel==0{assert!(actual.should_yield());return Ok(OwnedSemantic{bytes:[0;7]})}let mut bytes=[0;7];bytes.copy_from_slice(b"source!");actual.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()})?;actual.consume_fuel(1);Ok(OwnedSemantic{bytes})})}));let returned=answer.unwrap();assert_eq!(heap,(0,0));assert!(returned.receipt_refusal().is_none());assert_eq!(returned.raw_progress().unwrap(),caller.receipt());let semantic=returned.into_original().ok().unwrap().unwrap();assert_eq!(semantic.bytes,if fuel==0{[0;7]}else{*b"source!"});assert_eq!(observe(||drop(semantic)).1,(0,0));caller.turn(callback,|cx|{assert_eq!((cx.operation(),cx.generation()),(operation,generation));assert_eq!(cx.original_source_parent()?.source_identity()?,parent_identity);Ok(())}).unwrap();}
    NOW.with(|now|now.set(1002));let(answer,heap)=observe(||work(&mut caller,callback,4,200000,|parent,cx|child.with_context(parent,cx,RetainedCloneGrant{maximum_copy_bytes:6,..callback},|actual|{let mut bytes=[0;7];bytes.copy_from_slice(b"source!");assert!(actual.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()}).is_err());Ok(OwnedSemantic{bytes})})));let returned=answer.unwrap();assert_eq!(heap,(0,0));assert!(returned.admitted().is_none());assert!(returned.receipt_refusal().is_some());assert_eq!(returned.raw_progress().unwrap(),RetainedCloneProgress{copied_items:1,copied_bytes:7,..Default::default()});let returned=returned.into_original().err().unwrap();assert_eq!(returned.retained_original().unwrap().as_ref().unwrap().bytes,*b"source!");
    let(answer,heap)=observe(||work(&mut caller,callback,1,200000,|_,cx|{let(cursor,birth)=semio_framework_value::retirement::admit_owned_retirement(returned,cx.retained_grant()).ok().unwrap();cx.consume_retained(birth)?;cx.consume_fuel(1);Ok((cursor,birth))}));let(mut cursor,birth)=answer.unwrap();assert_eq!(heap,(birth.retained_capacity_bytes,0));born+=heap.0;
    for turn in 0..256{if cursor.terminal_is_empty(){break}let copy=cursor.next_copy_byte_demand().unwrap();let requested=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:copy,maximum_capacity_bytes:cursor.next_capacity_byte_demand(copy).unwrap(),maximum_release_bytes:cursor.next_release_byte_demand().unwrap(),maximum_depth:cursor.next_depth_demand().unwrap()};let(answer,heap)=observe(||work(&mut caller,requested,1,200000,|_,cx|{let step=cursor.close_step(cx.retained_grant())?;cx.consume_retained(step.progress())?;cx.consume_fuel(1);Ok(step)}));let progress=answer.unwrap().progress();assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.0;released+=heap.1;assert!(turn<255);}assert!(cursor.terminal_is_empty());let frame=birth.retained_capacity_bytes;let(answer,heap)=observe(||work(&mut caller,callback,1,200000,|_,cx|{let progress=RetainedCloneProgress{copied_items:1,released_bytes:frame,..Default::default()};assert!(progress.fits(cx.retained_grant()));drop(cursor);cx.consume_retained(progress)?;cx.consume_fuel(1);Ok(())}));answer.unwrap();assert_eq!(heap,(0,frame));released+=heap.1;
   }
   caller.cancel().cancel_now();for turn in 0..32{if source.as_ref().unwrap().terminal_is_empty(){break}let(answer,heap)=observe(||work(&mut caller,close,4,250000,|parent,cx|source.as_mut().unwrap().close_step(parent,cx)));let progress=answer.unwrap().progress();assert_eq!(progress,caller.receipt());assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));assert!(progress.fits(close));born+=heap.0;released+=heap.1;assert!(turn<31);}assert!(source.as_ref().unwrap().terminal_is_empty());assert_eq!(observe(||drop(source.take())).1,(0,0));
  }
  for turn in 0..64{if caller.terminal_is_empty(){break}let(answer,heap)=observe(||caller.retire_step(close));let progress=answer.unwrap().progress();assert!(progress.fits(close));assert_eq!(heap,(progress.retained_capacity_bytes,progress.released_bytes));born+=heap.0;released+=heap.1;assert!(turn<63);}assert!(caller.terminal_is_empty());assert_eq!(observe(||drop(caller)).1,(0,0));assert_eq!(born,released);println!("[DEBUG] originalChildSource cut={cut} parent99241/7 child211/19 originalLedgerOnce=true sameCancelNode=true actualInitiatingClock=true oneStock=true actualSupplier=true receivingOnce=true originalCloseCopy0=true birthRelease={born} terminalDrop0=true");
 }
}
